@pytest.mark.parametrize("case", CASES, ids=[c["id"] for c in CASES])
def test_cross_file_navigation_per_site_and_state(run, workdir, case):
    """CATCHES: cross-file hover/definition/references/rename that read the wrong source
    (disk instead of an open buffer or the reverse), miss a module, or answer with
    ranges or edits that differ from the reference server."""
    S.check(run, workdir, case, __file__)
